  async placeHold(body, username = "Customs Officer") {
    const prisma5 = getPrisma();
    if (isDbLive() && prisma5) {
      try {
        const unitStayId = Number(body.unitStayId) || 1;
        const created = await prisma5.hold.create({
          data: {
            unit_stay_id: unitStayId,
            hold_type_id: body.holdTypeId ? Number(body.holdTypeId) : 1,
            reason: body.reason || "Administrative hold applied",
            authority_ref: body.authorityRef || `HOLD-${Date.now().toString().slice(-4)}`,
            placed_at: /* @__PURE__ */ new Date(),
            placed_by_sub: username,
            status: "ACTIVE",
            createdby: "system"
          }
        });
        await prisma5.unit_stay.update({
          where: { unit_stay_id: unitStayId },
          data: { active_hold_count: { increment: 1 } }
        });
        const all = await this.getHolds();
        return all.find((h) => h.holdId === toNum(created.hold_id)) || all[0];
      } catch (err) {
        console.warn("[CargoService.placeHold] DB error:", err.message);
      }
    }
    const newH = {
      holdId: holds.length + 1,
      status: "ACTIVE",
      placedAt: (/* @__PURE__ */ new Date()).toISOString(),
      ...body
    };
    holds.push(newH);
    return newH;
  }
  async liftHold(holdId2, body, username = "Customs Officer") {
    const prisma5 = getPrisma();
    const id = Number(holdId2);
    if (isDbLive() && prisma5 && Number.isFinite(id)) {
      try {
        const existing = await prisma5.hold.findUnique({ where: { hold_id: id } });
        if (existing) {
          const updated = await prisma5.hold.update({
            where: { hold_id: id },
            data: {
              status: "LIFTED",
              lifted_at: /* @__PURE__ */ new Date(),
              lifted_by_sub: username,
              lift_reason: body.liftReason || "Authorized release"
            }
          });
          await prisma5.unit_stay.update({
            where: { unit_stay_id: existing.unit_stay_id },
            data: { active_hold_count: { decrement: 1 } }
          });
          const all = await this.getHolds();
          return all.find((h2) => h2.holdId === toNum(updated.hold_id)) || all[0];
        }
      } catch (err) {
        console.warn("[CargoService.liftHold] DB error:", err.message);
      }
    }
    const h = holds.find((x) => String(x.holdId) === String(holdId2));
    if (h) {
      h.status = "LIFTED";
      h.liftedAt = (/* @__PURE__ */ new Date()).toISOString();
      h.liftReason = body.liftReason;
    }
    return h;
  }
